const body = $input.first().json.body;

const numero = body.numero;
const nombre = body.nombre || 'Sin nombre';
const tratamiento = body.tratamiento_interes || 'No especificado';
const urgencia = body.urgencia || 'No especificada';
const disponibilidad = body.disponibilidad || 'No especificada';
const motivo = body.motivo_escalacion || 'El lead solicitó hablar con un humano';
const wa_phone_id = body.wa_phone_id;
const wa_staff = body.wa_staff_numero;

const timestamp = new Date().toLocaleString('es-CO', {
  timeZone: 'America/Bogota',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

const resumen = `👤 *Lead:* ${nombre} | ${numero}
💉 *Interés:* ${tratamiento}
⚡ *Urgencia:* ${urgencia}
📅 *Disponibilidad:* ${disponibilidad}
⚠️ *Motivo escalación:* ${motivo}
🕐 *Hora:* ${timestamp}

_Contactar lo antes posible_`;

return [{
  json: {
    numero,
    nombre,
    wa_phone_id,
    wa_staff,
    resumen,
    timestamp
  }
}];

